    while let Some(m) = port_matches.next() {
        let port_node = m.captures.first().unwrap().node;
        ports.extend(extract_ports_from_node(port_node, src));
    }

    Some(ModuleInfo {
        name,
        header_end,
        params,
        ports,
        port_names,
    })
}

