pub const HANDSHAKE_CLK: &str = "ap_clk";
/// Active-high reset generated by TAPA codegen
/// (`assign ap_rst = ~ap_rst_n`).
pub const HANDSHAKE_RST: &str = "ap_rst";
/// Vitis-HLS-internal inverted reset. TAPA never generates this name;
/// it is recognized and stripped from HLS output.
pub const HLS_RST_INV: &str = "ap_rst_n_inv";
pub const HANDSHAKE_RST_N: &str = "ap_rst_n";
pub const HANDSHAKE_START: &str = "ap_start";
pub const HANDSHAKE_DONE: &str = "ap_done";
pub const HANDSHAKE_IDLE: &str = "ap_idle";
pub const HANDSHAKE_READY: &str = "ap_ready";

