pub fn axi_subport_from_suffix(suffix: &str) -> &str {
    let s = suffix.trim_start_matches('_');
    s.strip_prefix("AR")
        .or_else(|| s.strip_prefix("AW"))
        .or_else(|| s.strip_prefix('R'))
        .or_else(|| s.strip_prefix('W'))
        .or_else(|| s.strip_prefix('B'))
        .unwrap_or(s)
