   100	/// Fallback: capture raw `(* ... *)` when structured parsing fails.
   101	fn raw_attribute(input: &str) -> IResult<&str, Pragma> {
   102	    let start = input;
   103	    let (input, _) = tag("(*").parse(input)?;
   104	    let (input, _content) = take_until("*)").parse(input)?;
   105	    let (input, _) = tag("*)").parse(input)?;
   106	    let consumed = &start[..start.len() - input.len()];
   107	    Ok((
   108	        input,
   109	        Pragma {
   110	            key: String::new(),
   111	            value: None,
   112	            raw_line: consumed.to_owned(),
   113	        },
   114	    ))
   115	}
   116	
   117	/// Parse zero or more attributes before a declaration.
   118	fn attributes(input: &str) -> IResult<&str, Vec<Pragma>> {
   119	    let mut pragmas = Vec::new();
   120	    let mut remaining = input;
   121	    loop {
   122	        let (next, _) = ws(remaining)?;
   123	        if !next.starts_with("(*") {
   124	            remaining = next;
   125	            break;
   126	        }
   127	        // Try structured parse first, then raw fallback.
   128	        if let Ok((after, pragma)) = attribute(next) {
   129	            pragmas.push(pragma);
   130	            remaining = after;
   131	        } else if let Ok((after, raw_pragma)) = raw_attribute(next) {
   132	            pragmas.push(raw_pragma);
   133	            remaining = after;
   134	        } else {
   135	            remaining = next;
   136	            break;
   137	        }
   138	    }
   139	    Ok((remaining, pragmas))
   140	}
