   144	/// Parse signal kind keyword.
   145	fn signal_kind(input: &str) -> IResult<&str, SignalKind> {
   146	    alt((
   147	        value(SignalKind::Wire, tag("wire")),
   148	        value(SignalKind::Reg, tag("reg")),
   149	    ))
