   151	}
   152	
   153	/// Parse: `wire|reg [signed] [width] name1 [dims] [= expr], name2 [dims] [= expr], ... ;`
   154	/// Returns multiple signals for comma-separated declarations.
   155	fn signal_declarations(input: &str) -> IResult<&str, Vec<Signal>> {
   156	    let (input, kind) = signal_kind(input)?;
   157	    let (input, _) = multispace0(input)?;
   158	    let input = skip_signedness(input);
   159	    let (input, w) = opt(terminated(width_spec, multispace0)).parse(input)?;
   160	
   161	    let mut sigs = Vec::new();
   162	    let mut cursor = input;
   163	    loop {
   164	        let (rest, _) = multispace0(cursor)?;
   165	        let (rest, name) = identifier(rest)?;
   166	        let (rest, _) = space0(rest)?;
   167	        let rest = skip_bracketed_dimensions(rest);
   168	        // Skip optional `= expr`.
   169	        let (rest, _) = space0(rest)?;
