   171	            // Skip the assignment expression, respecting nested braces.
   172	            skip_to_comma_or_semi_balanced(rest)
   173	        } else {
   174	            rest
   175	        };
   176	        sigs.push(Signal {
   177	            name: name.to_owned(),
   178	            kind,
   179	            width: w.clone(),
   180	            attribute: None,
   181	        });
   182	        let (rest, _) = space0(rest)?;
   183	        if let Some(after_comma) = rest.strip_prefix(',') {
   184	            cursor = after_comma;
   185	        } else {
   186	            let (rest, _) = char(';').parse(rest)?;
   187	            return Ok((rest, sigs));
   188	        }
   189	    }
   190	}
