   192	/// Skip an assignment expression until `,` or `;` at brace/bracket depth 0.
   193	fn skip_to_comma_or_semi_balanced(input: &str) -> &str {
   194	    let mut depth: u32 = 0;
   195	    for (i, b) in input.bytes().enumerate() {
   196	        match b {
   197	            b'{' | b'(' | b'[' => depth += 1,
   198	            b'}' | b')' | b']' if depth > 0 => depth -= 1,
   199	            b',' | b';' if depth == 0 => return &input[i..],
   200	            _ => {}
   201	        }
   202	    }
   203	    input
   204	}
   205	
   206	/// Skip zero or more bracketed dimensions like `[0:N-1]` after a signal name.
   207	fn skip_bracketed_dimensions(mut input: &str) -> &str {
   208	    while input.starts_with('[') {
   209	        if let Some(close) = input.find(']') {
   210	            input = input[close + 1..].trim_start();
   211	        } else {
   212	            break;
   213	        }
   214	    }
   215	    input
   216	}
   217	
   218	/// Skip `signed` or `unsigned` qualifier if present.
   219	fn skip_signedness(input: &str) -> &str {
   220	    for kw in &["signed", "unsigned"] {
   221	        if let Some(rest) = input.strip_prefix(kw) {
   222	            if rest.starts_with(|c: char| c.is_ascii_whitespace() || c == '[') {
   223	                return rest.trim_start();
   224	            }
   225	        }
   226	    }
   227	    input
   228	}
