    21	/// Regex patterns for cleanup: HLS-generated artifacts to remove.
    22	static REGSLICE_PATTERN: LazyLock<Regex> =
    23	    LazyLock::new(|| Regex::new(r"(?m)^.*_regslice_both\b.*$\n?").unwrap());
    24	static AP_BLOCK_PATTERN: LazyLock<Regex> =
    25	    LazyLock::new(|| Regex::new(r"(?m)^.*ap_ST_fsm_state\d+_blk\b.*$\n?").unwrap());
    26	/// Remove HLS FSM parameter declarations.
    27	static FSM_PARAM_PATTERN: LazyLock<Regex> =
    28	    LazyLock::new(|| Regex::new(r"(?m)^.*ap_ST_fsm_state\d+\b.*$\n?").unwrap());
    29	/// Remove `ap_CS_fsm` and `ap_NS_fsm` declarations and assignments.
    30	static CS_NS_FSM_PATTERN: LazyLock<Regex> =
    31	    LazyLock::new(|| Regex::new(r"(?m)^.*\bap_[CN]S_fsm\b.*$\n?").unwrap());
    32	/// Remove initial blocks (power-on initialization).
    33	static INITIAL_BLOCK_PATTERN: LazyLock<Regex> =
    34	    LazyLock::new(|| Regex::new(r"(?ms)^initial begin\n.*?end\n?").unwrap());
    35	/// Remove `ap_ce_reg` declarations.
    36	static AP_CE_PATTERN: LazyLock<Regex> =
    37	    LazyLock::new(|| Regex::new(r"(?m)^.*\bap_ce_reg\b.*$\n?").unwrap());
    38	/// Remove HLS-internal inverted-reset declarations and assignments.
    39	static RST_INV_PATTERN: LazyLock<Regex> = LazyLock::new(|| {
    40	    Regex::new(&format!(r"(?m)^.*\b{}\b.*$\n?", tapa_protocol::HLS_RST_INV)).unwrap()
    41	});
    42	/// Remove placeholder top-level handshake assigns from the HLS wrapper.
    43	static AP_HANDSHAKE_ASSIGN_PATTERN: LazyLock<Regex> =
    44	    LazyLock::new(|| Regex::new(r"(?m)^\s*assign\s+ap_(?:done|ready|idle)\s*=.*;\s*\n?").unwrap());
