    46	/// A mutable view of a `VerilogModule` that tracks additions and
    47	/// body text modifications.
    48	///
    49	/// Ports and signals are mutated in place on `inner` (mirroring how
    50	/// `cleanup_hls_artifacts`/`demote_*` already operate). Only append-only
    51	/// fragments with no parsed original — instances, assigns, and always
    52	/// blocks — are tracked separately.
    53	pub struct MutableModule {
    54	    /// The parsed module; its `ports`/`signals`/`parameters` are mutated
    55	    /// in place as the upper-task instrumentation adds/removes them.
    56	    pub inner: VerilogModule,
    57	    /// Raw body text between port declarations and `endmodule`.
    58	    pub body_text: String,
    59	    /// New module instances to append to the body.
    60	    added_instances: Vec<ModuleInstance>,
    61	    /// New continuous assigns to append.
    62	    added_assigns: Vec<ContinuousAssign>,
    63	    /// New always blocks to append.
    64	    added_always: Vec<AlwaysBlock>,
    65	}
    66	
    67	impl MutableModule {
    68	    /// Create a mutable module from a parsed `VerilogModule`.
    69	    ///
    70	    /// Extracts the body text from the source by finding content after
    71	    /// the last port/signal declaration and before `endmodule`.
    72	    pub fn from_parsed(module: VerilogModule) -> Self {
    73	        let body_text = extract_body_text(&module.source);
    74	        Self {
    75	            inner: module,
    76	            body_text,
    77	            added_instances: Vec::new(),
    78	            added_assigns: Vec::new(),
    79	            added_always: Vec::new(),
    80	        }
    81	    }
    82	
    83	    /// Add a port, rejecting duplicates.
    84	    pub fn add_port(&mut self, port: Port) -> Result<(), BuilderError> {
    85	        if port.name.is_empty() {
    86	            return Err(BuilderError::EmptyName);
    87	        }
    88	        if self.has_port(&port.name) {
    89	            return Err(BuilderError::DuplicatePort(port.name));
    90	        }
    91	        self.inner.ports.push(port);
    92	        Ok(())
    93	    }
    94	
    95	    /// Add a signal, rejecting duplicates.
    96	    pub fn add_signal(&mut self, signal: Signal) -> Result<(), BuilderError> {
    97	        if signal.name.is_empty() {
    98	            return Err(BuilderError::EmptyName);
    99	        }
   100	        if self.has_signal(&signal.name) {
   101	            return Err(BuilderError::DuplicateSignal(signal.name));
   102	        }
   103	        self.inner.signals.push(signal);
   104	        Ok(())
   105	    }
   106	
   107	    /// Add a module instance to the body.
   108	    pub fn add_instance(&mut self, instance: ModuleInstance) {
   109	        self.added_instances.push(instance);
   110	    }
   111	
   112	    /// Add a continuous assign to the body.
   113	    pub fn add_assign(&mut self, assign: ContinuousAssign) {
   114	        self.added_assigns.push(assign);
   115	    }
   116	
   117	    /// Add an always block to the body.
   118	    pub fn add_always(&mut self, always: AlwaysBlock) {
   119	        self.added_always.push(always);
   120	    }

