    12	/// A parsed Verilog module interface.
    13	///
    14	/// Contains all interface elements extracted from a TAPA-generated
    15	/// Verilog module: ports, parameters, signals, pragmas, and the
    16	/// raw source text.
    17	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    18	pub struct VerilogModule {
    19	    /// Module name.
    20	    pub name: String,
    21	    /// Ports with direction and width.
    22	    pub ports: Vec<Port>,
    23	    /// Module parameters with defaults.
    24	    pub parameters: Vec<Parameter>,
    25	    /// Signal declarations (wire/reg).
    26	    pub signals: Vec<Signal>,
    27	    /// Pragmas extracted from attributes.
    28	    pub pragmas: Vec<Pragma>,
    29	    /// Raw Verilog source text, preserved verbatim.
    30	    pub source: String,
    31	}
    32	
    33	/// Vitis-generated RTL infixes tried when looking up a FIFO port by its
    34	/// logical argument name.
    35	pub const FIFO_INFIXES: &[&str] = &["_V", "_r", "_s", ""];
    36	
    37	/// The port-name convention belongs to the schema, so that `tapa-codegen`,
    38	/// `tapa pack` and `frt-cosim` cannot drift apart on it. Re-exported here
    39	/// because RTL identifiers are where it gets applied.
    40	pub use tapa_ir::port::{sanitize_array_name, sanitize_identifier_name};
    41	
    42	impl VerilogModule {
    43	    /// Parse a Verilog module header from source text.
    44	    pub fn parse(source: &str) -> Result<Self, ParseError> {
    45	        let trimmed = source.trim();
    46	        if trimmed.is_empty() {
    47	            return Err(ParseError::EmptyInput);
    48	        }
    49	        parser::parse_module(source)
    50	    }
    51	
    52	    /// Find a port by exact name.
    53	    pub fn find_port(&self, name: &str) -> Option<&Port> {
    54	        self.ports.iter().find(|p| p.name == name)
    55	    }
    56	
    57	    /// Find a port by prefix and suffix.
    58	    pub fn find_port_by_affixes(&self, prefix: &str, suffix: &str) -> Option<&Port> {
    59	        self.ports
    60	            .iter()
    61	            .find(|p| p.name.starts_with(prefix) && p.name.ends_with(suffix))
    62	    }
    63	
    64	    /// Resolve a FIFO / stream port by its logical base name and a suffix
    65	    /// like `_din`, `_dout`, `_full_n`, `_empty_n`, `_read`, `_write`.
    66	    ///
    67	    /// 1. Sanitize array-style names (`a[3]` → `a_3`).
    68	    /// 2. Try each `FIFO_INFIXES` entry in order (`_V`, `_r`, `_s`, `""`)
    69	    ///    to find a port named `{base}{infix}{suffix}`.
    70	    /// 3. If the original name was `foo[0]`, also try `{foo}{infix}{suffix}`
    71	    ///    as a singleton-array fallback.
    72	    pub fn get_port_of(&self, fifo: &str, suffix: &str) -> Option<&Port> {
    73	        let sanitized = sanitize_array_name(fifo);
    74	        for infix in FIFO_INFIXES {
    75	            let name = format!("{sanitized}{infix}{suffix}");
    76	            if let Some(port) = self.find_port(&name) {
    77	                return Some(port);
    78	            }
    79	        }
    80	        if let Some((base, idx)) = match_array_name(fifo) {
    81	            if idx == 0 {
    82	                for infix in FIFO_INFIXES {
    83	                    let name = format!("{base}{infix}{suffix}");
    84	                    if let Some(port) = self.find_port(&name) {
    85	                        return Some(port);
    86	                    }
    87	                }
    88	            }
    89	        }
    90	        None
    91	    }
    92	}
    93	
    94	/// Match `name[idx]` and return `(name, idx)`.
    95	#[must_use]
    96	pub fn match_array_name(name: &str) -> Option<(&str, u32)> {
    97	    let lb = name.find('[')?;
    98	    let rb = name.rfind(']')?;
    99	    if rb <= lb + 1 || !name.ends_with(']') {
   100	        return None;
   101	    }
   102	    let base = &name[..lb];
   103	    let idx_str = &name[lb + 1..rb];
   104	    if base.is_empty() || idx_str.is_empty() {
   105	        return None;
   106	    }
   107	    if !base.chars().all(|c| c.is_alphanumeric() || c == '_') {
   108	        return None;
   109	    }
   110	    let idx: u32 = idx_str.parse().ok()?;
   111	    Some((base, idx))
   112	}
