   122	        let (next, _) = ws(remaining)?;
   123	        if !next.starts_with("(*") {
   124	            remaining = next;
   125	            break;
   126	        }
   127	        // Try structured parse first, then raw fallback.
   128	        if let Ok((after, pragma)) = attribute(next) {
   129	            pragmas.push(pragma);
   130	            remaining = after;
   131	        } else if let Ok((after, raw_pragma)) = raw_attribute(next) {
   132	            pragmas.push(raw_pragma);
   133	            remaining = after;
   134	        } else {
   135	            remaining = next;
   136	            break;
   137	        }
   138	    }
