256	fn extract_parameters_from_node(node: Node, src: &[u8]) -> Vec<Parameter> {
257	    let mut width: Option<Width> = None;
258	    let mut params = Vec::new();
259	
260	    for i in 0..node.child_count() {
261	        let child = node.child(i).unwrap();
262	        if child.kind() == "data_type_or_implicit" || child.kind() == "data_type" {
263	            width = extract_width(child, src).or(width);
264	        }
265	        if child.kind() == "list_of_param_assignments" {
266	            for j in 0..child.child_count() {
267	                let c = child.child(j).unwrap();
268	                if c.kind() == "param_assignment" {
269	                    let mut name = None;
270	                    let mut default_str = None;
271	                    for k in 0..c.child_count() {
272	                        let d = c.child(k).unwrap();
273	                        match d.kind() {
274	                            "simple_identifier" => name = Some(text_of(d, src).to_owned()),
275	                            "constant_param_expression"
276	                            | "constant_mintypmax_expression"
277	                            | "constant_expression"
278	                            | "constant_primary"
279	                            | "primary_literal"
280	                            | "integral_number"
281	                            | "decimal_number"
282	                            | "octal_number"
283	                            | "binary_number"
284	                            | "hex_number"
285	                            | "real_number"
286	                            | "unbased_unsized_literal"
287	                                if default_str.is_none() =>
288	                            {
289	                                default_str = Some(text_of(d, src).trim().to_owned());
290	                            }
291	                            _ => {}
292	                        }
293	                    }
294	                    if let (Some(n), Some(d)) = (name, default_str) {
295	                        params.push(Parameter {
296	                            name: n,
297	                            default: tokenize_expression(&d),
298	                            width: width.clone(),
299	                        });
300	                    }
301	                }
302	            }
303	        }
304	    }
305	    params
306	}
