327	/// Scan the tree-sitter CST for `ERROR` nodes that correspond to
328	/// declarations the old nom parser would have validated.
329	///
330	/// Ignores ERROR nodes inside procedural blocks, assignments, and
331	/// instantiations — those are skipped by the body loop anyway.
332	pub fn first_parse_error(source: &str) -> Option<ParseIssue> {
333	    fn walk(node: Node, src: &[u8]) -> Option<ParseIssue> {
334	        if node.kind() == "ERROR" || node.is_error() {
335	            let text = text_of(node, src);
336	            let trimmed = text.trim_start();
337	            if trimmed.starts_with("parameter") {
338	                return Some(ParseIssue::MalformedParameter);
339	            }
340	            if trimmed.starts_with("input")
341	                || trimmed.starts_with("output")
342	                || trimmed.starts_with("inout")
343	            {
344	                return Some(ParseIssue::MalformedPort);
345	            }
346	            // Other ERROR nodes (inside procedural blocks, etc.) are
347	            // ignored because the old parser skipped those constructs.
348	            return None;
349	        }
350	        for i in 0..node.child_count() {
351	            if let Some(found) = walk(node.child(i).unwrap(), src) {
352	                return Some(found);
353	            }
354	        }
355	        None
356	    }
357	
358	    let mut parser = sv_parser();
359	    let tree = parser.parse(source.as_bytes(), None)?;
360	    let root = tree.root_node();
361	    let src = source.as_bytes();
362	    walk(root, src)
363	}
